<?php
declare(strict_types=1);require dirname(__DIR__).'/private/app.php';require dirname(__DIR__).'/private/lifecycle/payments.php';security_headers();header('Cache-Control: private, no-store');header('X-Robots-Tag: noindex,nofollow');
try{$a=cc_actor(($_GET['mode']??'customer')!=='owner');lc_finance_gate();$id=filter_var($_GET['id']??'',FILTER_VALIDATE_INT);if(!$id||$id<1)crm_fail(404,'Запрос оплаты не найден.');$i=lc_invoice($a,(int)$id);if(!hash_equals($i['snapshot_hash'],hash('sha256',$i['snapshot'])))crm_fail(503,'Целостность запроса оплаты не подтверждена.');$s=json_decode($i['snapshot'],true,512,JSON_THROW_ON_ERROR);$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}catch(CrmFailure $e){fail($e->status,$e->getMessage(),'finance_error');}catch(CustomerFailure $e){fail($e->status,$e->getMessage(),$e->errorCode);}catch(Throwable $e){server_error($e);}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Запрос оплаты <?= $e($i['number']) ?></title><link rel="stylesheet" href="operations.css"><link rel="stylesheet" href="collaboration.css"></head><body><main class="portal print-document"><h1>Запрос оплаты №<?= $e($i['number']) ?></h1><p>Не является официальным чеком НПД.</p><p>Заказ №<?= $e($s['order']['number']) ?>. Дата <?= $e($s['issued_at']) ?> UTC. Сумма <?= $e(bill_decimal((int)$i['total_minor'])) ?> RUB. Срок <?= $e($i['due_on']) ?>.</p><p>Исполнитель: <?= $e($s['merchant']['legal_name']) ?>. <?= $e($s['merchant']['registration']) ?></p><p>Платёжные реквизиты: <?= $e($s['merchant']['payment_instructions']) ?></p><?php foreach($s['rendered'] as $k=>$text): ?><section><h2><?= $e(lc_sections()[$k]) ?></h2><div class="document-body"><?= $e($text) ?></div></section><?php endforeach; ?><p>Шаблон №<?= $e($s['template']['id']) ?> v<?= $e($s['template']['revision_number']) ?>. Подписанный договор: SHA-256 <?= $e($s['agreement_hash']) ?>.</p><p>SHA-256 запроса оплаты: <?= $e($i['snapshot_hash']) ?></p><button id="print-document">Печать / сохранить PDF</button></main><script src="collab-print.js"></script></body></html>
